use glam::DVec3 as V;use ingetrazo_core::{image_plane::ImagePlane,groups::Group,scene::SelectionItem,math::Ray};use ingetrazo_gui::IngeTrazoApp;use ingetrazo_tools::base::{ToolContext,ToolType};
fn ctx(p:V)->ToolContext{ToolContext::new(p,Ray::new(V::new(0.5,0.5,10.),-V::Z))}fn state(a:&IngeTrazoApp)->serde_json::Value{serde_json::json!({"origin":a.scene.image_planes[0].origin,"active":a.active_tool_type==ToolType::Move&&a.active_tool.snap_anchor().is_some(),"editing":!a.component_edit_stack.is_empty(),"undo":a.undo_stack.len()})}
fn main(){let mut rows=serde_json::Map::new();for case in ["finish_live","cancel_then_finish"]{let mut a=IngeTrazoApp::new();a.system_clipboard=None;let mut group=Group::new("Leaf");group.mesh.add_vertex(V::ZERO);group.mesh.add_vertex(V::X);group.mesh.add_vertex(V::Y);group.mesh.add_face(vec![0,1,2],vec![]);a.scene.groups.push(group);a.scene.image_planes.push(ImagePlane::new("scan",V::new(0.125,-1.25,2.5),V::X*2.,V::Y*2.));a.scene.select(SelectionItem::Group(0));a.begin_component_edit();a.scene.clear_selection();a.scene.select(SelectionItem::ImagePlane(0));a.set_tool(ToolType::Move);let mut states=vec![state(&a)];a.dispatch_tool_click(&ctx(V::ZERO));a.dispatch_tool_move(&ctx(V::new(0.7,1.2,-0.3)));a.dispatch_tool_move(&ctx(V::new(0.9,0.4,0.8)));states.push(state(&a));if case=="cancel_then_finish"{a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));}a.finish_component_edit();states.push(state(&a));a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));rows.insert(case.into(),serde_json::json!(states));}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
